17	package org.apache.camel.component.platform.http.vertx;
18	
19	import java.io.IOException;
20	import java.io.InputStream;
21	import java.nio.ByteBuffer;
22	import java.nio.channels.Channels;
23	import java.nio.channels.ReadableByteChannel;
24	import java.util.concurrent.locks.Lock;
25	import java.util.concurrent.locks.ReentrantLock;
26	
27	import io.vertx.core.AsyncResult;
28	import io.vertx.core.Context;
29	import io.vertx.core.Future;
30	import io.vertx.core.Handler;
31	import io.vertx.core.Vertx;
32	import io.vertx.core.buffer.Buffer;
33	import io.vertx.core.streams.ReadStream;
34	import io.vertx.core.streams.impl.InboundBuffer;
35	import org.apache.camel.util.IOHelper;
36	import org.slf4j.Logger;
37	import org.slf4j.LoggerFactory;
38	
39	/**
40	 * {@link ReadStream} that can process an {@link InputStream} in an asynchronous way, so that the content can be pumped
41	 * to the {@link io.vertx.core.streams.WriteStream} of an {@link io.vertx.core.http.HttpServerResponse}.
42	 */
43	public class AsyncInputStream implements ReadStream<Buffer> {
44	    private static final Logger LOG = LoggerFactory.getLogger(AsyncInputStream.class);
45	
46	    private final Lock lock = new ReentrantLock();
47	    private final ReadableByteChannel channel;
48	    private final Vertx vertx;
49	    private final Context context;
50	    private final InboundBuffer<Buffer> queue;
51	    private long readPos;
52	    private boolean closed;
53	    private boolean readInProgress;
54	    private Handler<Buffer> dataHandler;
55	    private Handler<Void> endHandler;
56	    private Handler<Throwable> exceptionHandler;
57	
58	    public AsyncInputStream(Vertx vertx, Context context, InputStream inputStream) {
59	        this.vertx = vertx;
60	        this.context = context;
61	        this.channel = Channels.newChannel(inputStream);
62	        this.queue = new InboundBuffer<>(context, 0);
63	        queue.handler(buffer -> {
64	            if (buffer.length() > 0) {
65	                handleData(buffer);
66	            } else {
67	                handleEnd();
68	            }
69	        });
70	        queue.drainHandler(v -> doRead());
71	    }
72	
73	    @Override
74	    public AsyncInputStream endHandler(Handler<Void> endHandler) {
75	        lock.lock();
76	        try {
77	            checkStreamClosed();
78	            this.endHandler = endHandler;
79	            return this;
80	        } finally {
81	            lock.unlock();
82	        }
83	    }
84	
85	    @Override
86	    public AsyncInputStream exceptionHandler(Handler<Throwable> exceptionHandler) {
87	        lock.lock();
88	        try {
89	            checkStreamClosed();
90	            this.exceptionHandler = exceptionHandler;
91	            return this;
92	        } finally {
93	            lock.unlock();
94	        }
95	    }
96	
97	    @Override
98	    public AsyncInputStream handler(Handler<Buffer> handler) {
99	        lock.lock();
100	        try {
101	            checkStreamClosed();
102	            this.dataHandler = handler;
103	            if (this.dataHandler != null && !this.closed) {
104	                this.doRead();
105	            } else {
106	                queue.clear();
107	            }
108	            return this;
109	        } finally {
110	            lock.unlock();
111	        }
112	    }
113	
114	    @Override
115	    public AsyncInputStream pause() {
116	        lock.lock();
117	        try {
118	            checkStreamClosed();
119	            queue.pause();
120	            return this;
121	        } finally {
122	            lock.unlock();
123	        }
124	    }
125	
126	    @Override
127	    public AsyncInputStream resume() {
128	        lock.lock();
129	        try {
130	            checkStreamClosed();
131	            queue.resume();
132	            return this;
133	        } finally {
134	            lock.unlock();
135	        }
136	    }
137	
138	    @Override
139	    public ReadStream<Buffer> fetch(long amount) {
140	        checkStreamClosed();
141	        queue.fetch(amount);
142	        return this;
143	    }
144	
145	    public void close(Handler<AsyncResult<Void>> handler) {
146	        closeInternal(handler);
147	    }
148	
149	    private void checkStreamClosed() {
150	        if (this.closed) {
151	            throw new IllegalStateException("Stream closed");
152	        }
153	    }
154	
155	    private void checkContext() {
156	        Context contextToCheck = vertx.getOrCreateContext();
157	        if (!contextToCheck.equals(context)) {
158	            throw new IllegalStateException(
159	                    "AsyncInputStream must only be used in the context that created it, expected: " + this.context
160	                                            + " actual " + contextToCheck);
161	        }
162	    }
163	
164	    private void closeInternal(Handler<AsyncResult<Void>> handler) {
165	        lock.lock();
166	        try {
167	            closed = true;
168	            doClose(handler);
169	        } finally {
170	            lock.unlock();
171	        }
172	    }
173	
174	    private void doClose(Handler<AsyncResult<Void>> handler) {
175	        try {
176	            channel.close();
177	            if (handler != null) {
178	                this.vertx.runOnContext(v -> handler.handle(Future.succeededFuture()));
179	            }
180	        } catch (IOException e) {
181	            if (handler != null) {
182	                this.vertx.runOnContext(v -> handler.handle(Future.failedFuture(e)));
183	            }
184	        }
185	    }
186	
187	    private void doRead() {
188	        checkStreamClosed();
189	        doRead(ByteBuffer.allocate(IOHelper.DEFAULT_BUFFER_SIZE));
190	    }
191	
192	    private void doRead(ByteBuffer buffer) {
193	        lock.lock();
194	        try {
195	            if (!readInProgress) {
196	                readInProgress = true;
197	                Buffer buff = Buffer.buffer(IOHelper.DEFAULT_BUFFER_SIZE);
198	                doRead(buff, 0, buffer, readPos, result -> {
199	                    if (result.succeeded()) {
200	                        readInProgress = false;
201	                        Buffer updatedBuffer = result.result();
202	                        readPos += updatedBuffer.length();
203	                        if (queue.write(updatedBuffer) && updatedBuffer.length() > 0) {
204	                            doRead(buffer);
205	                        }
206	                    } else {
207	                        handleException(result.cause());
208	                    }
209	                });
210	            }
211	        } finally {
212	            lock.unlock();
213	        }
214	    }
215	
216	    private void doRead(Buffer writeBuff, int offset, ByteBuffer buffer, long position, Handler<AsyncResult<Buffer>> handler) {
217	        vertx.executeBlocking(() -> channel.read(buffer))
218	                .onComplete(result -> {
219	                    if (result.succeeded()) {
220	                        Integer bytesRead = result.result();
221	                        if (bytesRead == -1) {
222	                            // EOF
223	                            context.runOnContext((v) -> {
224	                                buffer.flip();
225	                                writeBuff.setBytes(offset, buffer);
226	                                buffer.compact();
227	                                handler.handle(Future.succeededFuture(writeBuff));
228	                            });
229	                        } else if (buffer.hasRemaining()) {
230	                            // Read from the next offset
231	                            context.runOnContext((v) -> {
232	                                doRead(writeBuff, offset, buffer, position + bytesRead, handler);
233	                            });
234	                        } else {
235	                            // All data is written
236	                            context.runOnContext((v) -> {
237	                                buffer.flip();
238	                                writeBuff.setBytes(offset, buffer);
239	                                buffer.compact();
240	                                handler.handle(Future.succeededFuture(writeBuff));
241	                            });
242	                        }
243	                    } else {
244	                        context.runOnContext((v) -> handler.handle(Future.failedFuture(result.cause())));
245	                    }
246	                });
247	    }
248	
249	    private void handleData(Buffer buffer) {
250	        Handler<Buffer> handler;
251	        lock.lock();
252	        try {
253	            handler = this.dataHandler;
254	        } finally {
255	            lock.unlock();
256	        }
257	        if (handler != null) {
258	            checkContext();
259	            handler.handle(buffer);
260	        }
261	    }
262	
263	    private void handleEnd() {
264	        Handler<Void> endHandler;
265	        lock.lock();
266	        try {
267	            dataHandler = null;
268	            endHandler = this.endHandler;
269	        } finally {
270	            lock.unlock();
271	        }
272	        if (endHandler != null) {
273	            checkContext();
274	            endHandler.handle(null);
275	        }
276	    }
277	
278	    private void handleException(Throwable t) {
279	        if (exceptionHandler != null && t instanceof Exception) {
280	            exceptionHandler.handle(t);
281	        } else {
282	            if (LOG.isErrorEnabled()) {
283	                LOG.error("Unhandled error while processing stream", t);
284	            }
285	        }
286	    }
287	}
