73	/**
74	 * A {@link org.apache.camel.Consumer} for the {@link org.apache.camel.component.platform.http.spi.PlatformHttpEngine}
75	 * based on Vert.x Web.
76	 */
77	public class VertxPlatformHttpConsumer extends DefaultConsumer
78	        implements PlatformHttpConsumer, Suspendable {
79	
80	    private static final Logger LOGGER = LoggerFactory.getLogger(VertxPlatformHttpConsumer.class);
81	    private static final Pattern PATH_PARAMETER_PATTERN = Pattern.compile("\\{([^/}]+)\\}");
82	    private static final String PRE_AUTHENTICATED_EXCHANGE = VertxPlatformHttpConsumer.class.getName()
83	                                                             + ".preAuthenticatedExchange";
84	    private static final String AUTHORIZATION = "Authorization";
85	
86	    private final List<Handler<RoutingContext>> handlers;
87	    private final String fileNameExtWhitelist;
88	    private final boolean muteExceptions;
89	    private final boolean handleWriteResponseError;
90	    private final PlatformHttpSecurityHandler securityHandler;
91	    private final List<Route> routes = new ArrayList<>();
92	    private RestRegistry restRegistry;
93	    private Set<Method> methods;
94	    private String path;
95	    private VertxPlatformHttpRouter router;
96	    private HttpRequestBodyHandler httpRequestBodyHandler;
97	    private CookieConfiguration cookieConfiguration;
98	    private final String routerName;
99	
100	    public VertxPlatformHttpConsumer(PlatformHttpEndpoint endpoint,
101	                                     Processor processor,
102	                                     List<Handler<RoutingContext>> handlers,
103	                                     String routerName) {
104	        this(endpoint, processor, handlers, routerName, null);
105	    }
106	
107	    public VertxPlatformHttpConsumer(PlatformHttpEndpoint endpoint,
108	                                     Processor processor,
109	                                     List<Handler<RoutingContext>> handlers,
110	                                     String routerName,
111	                                     PlatformHttpSecurityHandler securityHandler) {
112	        super(endpoint, processor);
113	
114	        this.handlers = handlers;
115	        this.fileNameExtWhitelist
116	                = endpoint.getFileNameExtWhitelist() == null ? null : endpoint.getFileNameExtWhitelist().toLowerCase(Locale.US);
117	        this.muteExceptions = endpoint.isMuteException();
118	        this.handleWriteResponseError = endpoint.isHandleWriteResponseError();
119	        this.routerName = routerName;
120	        this.securityHandler = securityHandler;
121	    }
122	
123	    @Override
124	    public PlatformHttpEndpoint getEndpoint() {
125	        return (PlatformHttpEndpoint) super.getEndpoint();
126	    }
127	
128	    @Override
129	    protected void doInit() throws Exception {
130	        super.doInit();
131	
132	        // camel-rest is optional
133	        restRegistry = PluginHelper.getRestRegistry(getEndpoint().getCamelContext());
134	
135	        methods = Method.parseList(getEndpoint().getHttpMethodRestrict());
136	        path = configureEndpointPath(getEndpoint());  // in vertx-web we should replace path parameters from {xxx} to :xxx syntax
137	        router = VertxPlatformHttpRouter.lookup(getEndpoint().getCamelContext(), routerName);
138	        if (router == null) {
139	            // dynamic assigned port number, then lookup using -0
140	            router = VertxPlatformHttpRouter.lookup(getEndpoint().getCamelContext(), PLATFORM_HTTP_ROUTER_NAME_ZERO);
141	        }
142	        if (router == null) {
143	            throw new IllegalArgumentException("No PlatformHttpEngine created and setup in registry with name: " + routerName);
144	        }
145	        if (!getEndpoint().isHttpProxy() && getEndpoint().isUseStreaming()) {
146	            httpRequestBodyHandler = new StreamingHttpRequestBodyHandler(router.bodyHandler());
147	        } else if (!getEndpoint().isHttpProxy() && !getEndpoint().isUseBodyHandler()) {
148	            httpRequestBodyHandler = new NoOpHttpRequestBodyHandler(router.bodyHandler());
149	        } else {
150	            httpRequestBodyHandler = new DefaultHttpRequestBodyHandler(router.bodyHandler());
151	        }
152	        if (getEndpoint().isUseCookieHandler()) {
153	            cookieConfiguration = getEndpoint().getCookieConfiguration();
154	        }
155	    }
156	
157	    @Override
158	    protected void doStart() throws Exception {
159	        super.doStart();
160	
161	        if (restRegistry != null && startRestServicesContractFirst()) {
162	            // rest-dsl contract first using multiple routers per api endpoint
163	            return;
164	        }
165	
166	        // standard http consumer using a single router
167	        final Route newRoute = router.route(path);
168	        if (getEndpoint().getRequestTimeout() > 0) {
169	            newRoute.handler(TimeoutHandler.create(getEndpoint().getRequestTimeout()));
170	        }
171	        if (getEndpoint().getCamelContext().getRestConfiguration().isEnableCORS() && getEndpoint().getConsumes() != null) {
172	            ((RouteImpl) newRoute).setEmptyBodyPermittedWithConsumes(true);
173	        }
174	        if (!methods.equals(Method.getAll())) {
175	            methods.forEach(m -> newRoute.method(HttpMethod.valueOf(m.name())));
176	        }
177	        if (getEndpoint().getComponent().isServerRequestValidation()) {
178	            if (getEndpoint().getConsumes() != null) {
179	                //comma separated contentTypes has to be registered one by one
180	                for (String c : getEndpoint().getConsumes().split(",")) {
181	                    newRoute.consumes(c);
182	                }
183	            }
184	            if (getEndpoint().getProduces() != null) {
185	                //comma separated contentTypes has to be registered one by one
186	                for (String p : getEndpoint().getProduces().split(",")) {
187	                    newRoute.produces(p);
188	                }
189	            }
190	        }
191	        configureSecurityHandler(newRoute);
192	        httpRequestBodyHandler.configureRoute(newRoute);
193	        for (Handler<RoutingContext> handler : handlers) {
194	            newRoute.handler(handler);
195	        }
196	        newRoute.handler(this::handleRequest);
197	        this.routes.add(newRoute);
198	    }
199	
200	    @Override
201	    protected void doStop() throws Exception {
202	        this.routes.forEach(Route::remove);
203	        this.routes.clear();
204	        super.doStop();
205	    }
206	
207	    /**
208	     * Special start logic for Rest DSL with contract-first, which need to use fine-grained vertx router to make this
209	     * consistent with Camel, otherwise there is only 1 vertx router to handle all the API endpoints (coarse grained)
210	     * which distorts the observability in vertx and camel-quarkus.
211	     *
212	     * @return true if in rest-dsl contract-first mode, false if standard mode
213	     */
214	    protected boolean startRestServicesContractFirst() throws Exception {
215	        boolean matched = false;
216	        for (var r : restRegistry.listAllRestServices()) {
217	            // rest-dsl contract-first we need to create a new unique router per API endpoint
218	            String target = path;
219	            if (target.endsWith("*")) {
220	                target = target.substring(0, target.length() - 1);
221	            }
222	            if (r.isContractFirst() && target.equals(r.getBasePath())) {
223	                matched = true;
224	                String u = r.getBasePath() + r.getBaseUrl();
225	                u = configureEndpointPath(u); // in vertx-web we should replace path parameters from {xxx} to :xxx syntax
226	                String v = r.getMethod();
227	                String c = r.getConsumes();
228	                String p = r.getProduces();
229	
230	                Route sr = router.route(u);
231	                sr.method(HttpMethod.valueOf(v));
232	                if (getEndpoint().getComponent().isServerRequestValidation()) {
233	                    if (c != null) {
234	                        for (String cc : c.split(",")) {
235	                            sr.consumes(cc);
236	                        }
237	                    }
238	                    if (p != null) {
239	                        for (String pp : p.split(",")) {
240	                            sr.produces(pp);
241	                        }
242	                    }
243	                }
244	                configureSecurityHandler(sr);
245	                httpRequestBodyHandler.configureRoute(sr);
246	                for (Handler<RoutingContext> handler : handlers) {
247	                    sr.handler(handler);
248	                }
249	                sr.handler(this::handleRequest);
250	                this.routes.add(sr);
251	            }
252	        }
253	        for (var r : restRegistry.listAllRestSpecifications()) {
254	            // rest-dsl contract-first we need to see if there is an api spec
255	            // that should be exposed via a vertx http router
256	            String target = path;
257	            if (target.endsWith("*")) {
258	                target = target.substring(0, target.length() - 1);
259	            }
260	            if (r.isSpecification() && target.equals(r.getBasePath())) {
261	                String u = r.getBasePath() + r.getBaseUrl();
262	                String v = r.getMethod();
263	                String p = r.getProduces();
264	
265	                Route sr = router.route(u);
266	                sr.method(HttpMethod.valueOf(v));
267	                if (getEndpoint().getComponent().isServerRequestValidation()) {
268	                    if (p != null) {
269	                        for (String pp : p.split(",")) {
270	                            sr.produces(pp);
271	                        }
272	                    }
273	                }
274	                configureSecurityHandler(sr);
275	                httpRequestBodyHandler.configureRoute(sr);
276	                for (Handler<RoutingContext> handler : handlers) {
277	                    sr.handler(handler);
278	                }
279	                sr.handler(this::handleRequest);
280	                this.routes.add(sr);
281	            }
282	        }
283	        return matched;
284	    }
285	
286	    private String configureEndpointPath(PlatformHttpEndpoint endpoint) {
287	        String path = endpoint.getPath();
288	        if (endpoint.isMatchOnUriPrefix() && !path.endsWith("*")) {
289	            path += "*";
290	        }
291	        return configureEndpointPath(path);
292	    }
293	
294	    private String configureEndpointPath(String path) {
295	        // Transform from the Camel path param syntax /path/{key} to vert.x web's /path/:key
296	        return PATH_PARAMETER_PATTERN.matcher(path).replaceAll(":$1");
297	    }
298	
299	    protected void handleRequest(RoutingContext ctx) {
300	        if (isSuspended()) {
301	            handleSuspend(ctx);
302	            return;
303	        }
304	
305	        final Vertx vertx = ctx.vertx();
306	        final Exchange exchange = getOrCreateExchange(ctx);
307	        exchange.setPattern(ExchangePattern.InOut);
308	
309	        //
310	        // We do not know if any of the processing logic of the route is synchronous or not so we
311	        // need to process the request on a thread on the Vert.x worker pool.
312	        //
313	        // As example, assuming the platform-http component is configured as the transport provider
314	        // for the rest dsl, then the following code may result in a blocking operation that could
315	        // block Vert.x event-loop for too long if the target service takes long to respond, as
316	        // example in case the service is a knative service scaled to zero that could take some time
317	        // to become available:
318	        //
319	        //     rest("/results")
320	        //         .get("/{id}")
321	        //         .route()
322	        //             .removeHeaders("*", "CamelHttpPath")
323	        //             .to("rest:get:?bridgeEndpoint=true");
324	        //
325	
326	        // Note: any logic that needs to interrogate HTTP headers not provided by RoutingContext.parsedHeaders, should
327	        // be done inside of the following onComplete block, to ensure that the HTTP request is fully processed.
328	        processHttpRequest(exchange, ctx).onComplete(result -> {
329	            if (result.failed()) {
330	                handleFailure(exchange, ctx, result.cause());
331	                return;
332	            }
333	
334	            if (getEndpoint().isHttpProxy()) {
335	                handleProxy(ctx, exchange);
336	            }
337	
338	            if (getEndpoint().isUseBodyHandler()) {
339	                populateMultiFormData(ctx, exchange.getIn(), getEndpoint().getHeaderFilterStrategy());
340	            }
341	
342	            vertx.executeBlocking(() -> processExchange(exchange), false).onComplete(processExchangeResult -> {
343	                if (processExchangeResult.succeeded()) {
344	                    writeResponse(ctx, exchange, getEndpoint().getHeaderFilterStrategy(), muteExceptions)
345	                            .onComplete(writeResponseResult -> {
346	                                if (writeResponseResult.succeeded()) {
347	                                    handleExchangeComplete(exchange);
348	                                } else {
349	                                    handleFailure(exchange, ctx, writeResponseResult.cause());
350	                                }
351	                            });
352	                } else {
353	                    handleFailure(exchange, ctx, processExchangeResult.cause());
354	                }
355	            });
356	        });
357	    }
358	
359	    private void handleExchangeComplete(Exchange exchange) {
360	        doneUoW(exchange);
361	        releaseExchange(exchange, false);
362	    }
363	
364	    private void handleFailure(Exchange exchange, RoutingContext ctx, Throwable failure) {
365	        getExceptionHandler().handleException(
366	                "Failed handling platform-http endpoint " + getEndpoint().getPath(),
367	                failure);
368	        ctx.fail(failure);
369	        if (handleWriteResponseError && failure != null) {
370	            Exception existing = exchange.getException();
371	            if (existing != null) {
372	                failure.addSuppressed(existing);
373	            }
374	            exchange.setProperty(Exchange.EXCEPTION_CAUGHT, failure);
375	            exchange.setException(failure);
376	        }
377	        handleExchangeComplete(exchange);
378	    }
379	
380	    private Object processExchange(Exchange exchange) throws Exception {
381	        createUoW(exchange);
382	        getProcessor().process(exchange);
383	        return null;
384	    }
385	
386	    private void configureSecurityHandler(Route route) {
387	        if (securityHandler != null) {
388	            route.handler(this::handleSecurity);
389	        }
390	    }
391	
392	    private void handleSecurity(RoutingContext ctx) {
393	        if (isSuspended()) {
394	            handleSuspend(ctx);
395	            return;
396	        }
397	
398	        ctx.request().pause();
399	        Exchange exchange = createExchange(false);
400	        exchange.setPattern(ExchangePattern.InOut);
401	        Message in = initializeHttpMessage(exchange, ctx);
402	        populateCamelHeaders(ctx, in.getHeaders(), exchange, getEndpoint().getHeaderFilterStrategy());
403	
404	        ctx.vertx().executeBlocking(() -> securityHandler.authenticate(getEndpoint(), exchange), false)
405	                .onComplete(result -> {
406	                    if (result.failed()) {
407	                        ctx.request().resume();
408	                        handleFailure(exchange, ctx, result.cause());
409	                    } else if (Boolean.TRUE.equals(result.result())) {
410	                        exchange.getMessage().reset();
411	                        ctx.put(PRE_AUTHENTICATED_EXCHANGE, exchange);
412	                        ctx.next();
413	                        ctx.request().resume();
414	                    } else {
415	                        ctx.request().resume();
416	                        writeResponse(ctx, exchange, getEndpoint().getHeaderFilterStrategy(), muteExceptions)
417	                                .onComplete(writeResponseResult -> {
418	                                    if (writeResponseResult.succeeded()) {
419	                                        releaseExchange(exchange, false);
420	                                    } else {
421	                                        handleFailure(exchange, ctx, writeResponseResult.cause());
422	                                    }
423	                                });
424	                    }
425	                });
426	    }
427	
428	    private Exchange getOrCreateExchange(RoutingContext ctx) {
429	        Exchange exchange = ctx.get(PRE_AUTHENTICATED_EXCHANGE);
430	        return exchange != null ? exchange : createExchange(false);
431	    }
432	
433	    private static void handleSuspend(RoutingContext ctx) {
434	        ctx.response().setStatusCode(503);
435	        ctx.end();
436	    }
437	
438	    private static void handleProxy(RoutingContext ctx, Exchange exchange) {
439	        exchange.getExchangeExtension().setStreamCacheDisabled(true);
440	        final MultiMap httpHeaders = ctx.request().headers();
441	        exchange.getMessage().setHeader(Exchange.HTTP_HOST, httpHeaders.get("Host"));
442	        exchange.getMessage().removeHeader("Proxy-Connection");
443	    }
444	
445	    protected Future<Void> processHttpRequest(Exchange exchange, RoutingContext ctx) {
446	        // reuse existing http message if pooled
447	        Message in = initializeHttpMessage(exchange, ctx);
448	
449	        final String charset = ctx.parsedHeaders().contentType().parameter("charset");
450	        if (charset != null) {
451	            exchange.setProperty(ExchangePropertyKey.CHARSET_NAME, charset);
452	            in.setHeader(Exchange.HTTP_CHARACTER_ENCODING, charset);
453	        }
454	
455	        User user = ctx.user();
456	        if (user != null) {
457	            in.setHeader(VertxPlatformHttpConstants.AUTHENTICATED_USER, user);
458	        }
459	        if (getEndpoint().isUseCookieHandler()) {
460	            exchange.setProperty(Exchange.COOKIE_HANDLER, new VertxCookieHandler(ctx));
461	        }
462	
463	        return populateCamelMessage(ctx, exchange, in);
464	    }
465	
466	    private Message initializeHttpMessage(Exchange exchange, RoutingContext ctx) {
467	        Message in = exchange.getIn();
468	        if (in instanceof HttpMessage hm) {
469	            hm.init(exchange, ctx.request(), ctx.response());
470	        } else {
471	            in = new HttpMessage(exchange, ctx.request(), ctx.response());
472	            exchange.setMessage(in);
473	        }
474	        return in;
475	    }
476	
477	    protected Future<Void> populateCamelMessage(RoutingContext ctx, Exchange exchange, Message message) {
478	        final HeaderFilterStrategy headerFilterStrategy = getEndpoint().getHeaderFilterStrategy();
479	        populateCamelHeaders(ctx, message.getHeaders(), exchange, headerFilterStrategy);
480	        if (securityHandler != null) {
481	            message.removeHeader(AUTHORIZATION);
482	        }
483	        return httpRequestBodyHandler.handle(ctx, message);
484	    }
485	
486	    private void populateMultiFormData(
487	            RoutingContext ctx, Message message, HeaderFilterStrategy headerFilterStrategy) {
488	        final boolean isMultipartFormData = isMultiPartFormData(ctx);
489	        if (isFormUrlEncoded(ctx) || isMultipartFormData) {
490	            final MultiMap formData = ctx.request().formAttributes();
491	            final Map<String, Object> body = new HashMap<>();
492	            for (String key : formData.names()) {
493	                for (String value : formData.getAll(key)) {
494	                    if (headerFilterStrategy != null
495	                            && !headerFilterStrategy.applyFilterToExternalHeaders(key, value, message.getExchange())) {
496	                        appendEntry(message.getHeaders(), key, value);
497	                        if (getEndpoint().isPopulateBodyWithForm()) {
498	                            appendEntry(body, key, value);
499	                        }
500	                    }
501	                }
502	            }
503	
504	            if (!body.isEmpty()) {
505	                message.setBody(body);
506	            }
507	
508	            if (isMultipartFormData) {
509	                populateAttachments(ctx.fileUploads(), message);
510	            }
511	        }
512	    }
513	
514	    protected void populateAttachments(List<FileUpload> uploads, Message message) {
515	        message.setHeader(Exchange.ATTACHMENTS_SIZE, uploads.size());
516	        for (FileUpload upload : uploads) {
517	            final String name = upload.name();
518	            final String fileName = upload.fileName();
519	
520	            LOGGER.trace("HTTP attachment {} = {}", name, fileName);
521	
522	            // is the file name accepted
523	            boolean accepted = true;
524	
525	            if (fileNameExtWhitelist != null) {
526	                String ext = FileUtil.onlyExt(fileName);
527	                if (ext != null) {
528	                    ext = ext.toLowerCase(Locale.US);
529	                    if (!fileNameExtWhitelist.equals("*") && !fileNameExtWhitelist.contains(ext)) {
530	                        accepted = false;
531	                    }
532	                }
533	            }
534	            if (accepted) {
535	                final File localFile = new File(upload.uploadedFileName());
536	                final AttachmentMessage attachmentMessage = message.getExchange().getMessage(AttachmentMessage.class);
537	                attachmentMessage.addAttachment(name, new DataHandler(new CamelFileDataSource(localFile, fileName)));
538	
539	                // populate body in case there is only one attachment
540	                if (uploads.size() == 1) {
541	                    message.setHeader(Exchange.FILE_PATH, localFile.getAbsolutePath());
542	                    message.setHeader(Exchange.FILE_LENGTH, upload.size());
543	                    message.setHeader(Exchange.FILE_NAME, upload.fileName());
544	                    String ct = MimeTypeHelper.probeMimeType(upload.fileName());
545	                    if (ct == null) {
546	                        ct = upload.contentType();
547	                    }
548	                    if (ct != null) {
549	                        message.setHeader(Exchange.FILE_CONTENT_TYPE, ct);
550	                    }
551	                    message.setBody(localFile);
552	                }
553	            } else {
554	                LOGGER.debug(
555	                        "Cannot add file as attachment: {} because the file is not accepted according to fileNameExtWhitelist: {}",
556	                        fileName, fileNameExtWhitelist);
557	            }
558	        }
559	    }
560	
561	    class VertxCookieHandler implements CookieHandler {
562	
563	        private final RoutingContext routingContext;
564	
565	        VertxCookieHandler(RoutingContext routingContext) {
566	            this.routingContext = routingContext;
567	        }
568	
569	        @Override
570	        public void addCookie(String name, String value) {
571	            Cookie cookie = Cookie.cookie(name, value)
572	                    .setPath(cookieConfiguration.getCookiePath())
573	                    .setDomain(cookieConfiguration.getCookieDomain())
574	                    .setSecure(cookieConfiguration.isCookieSecure())
575	                    .setHttpOnly(cookieConfiguration.isCookieHttpOnly())
576	                    .setSameSite(getSameSite(cookieConfiguration.getCookieSameSite()));
577	            if (cookieConfiguration.getCookieMaxAge() != null) {
578	                cookie.setMaxAge(cookieConfiguration.getCookieMaxAge());
579	            }
580	            routingContext.response().addCookie(cookie);
581	        }
582	
583	        private CookieSameSite getSameSite(CookieConfiguration.CookieSameSite sameSite) {
584	            for (CookieSameSite css : CookieSameSite.values()) {
585	                // 'Strict', 'Lax', or 'None'
586	                if (css.toString().equals(sameSite.getValue())) {
587	                    return css;
588	                }
589	            }
590	            return null;
591	        }
592	
593	        @Override
594	        public String removeCookie(String name) {
595	            Cookie cookie = routingContext.response().removeCookie(name);
596	            return cookie == null ? null : cookie.getValue();
597	        }
598	
