39	import org.apache.camel.Message;
40	import org.apache.camel.NoTypeConversionAvailableException;
41	import org.apache.camel.TypeConverter;
42	import org.apache.camel.spi.HeaderFilterStrategy;
43	import org.apache.camel.support.ExceptionHelper;
44	import org.apache.camel.support.MessageHelper;
45	import org.apache.camel.support.ObjectHelper;
46	import org.apache.camel.support.http.HttpUtil;
47	import org.slf4j.Logger;
48	import org.slf4j.LoggerFactory;
