53	/*
54	 * Supporting class for the platform-http-vertx component.
55	 *
56	 * Please note that many of the methods in this class are part of the component's hot-path, therefore, please be mindful
57	 * about the performance implications of the code (i.e.: keep methods small, avoid costly operations, etc).
58	 */
59	public final class VertxPlatformHttpSupport {
60	    private static final Logger LOGGER = LoggerFactory.getLogger(VertxPlatformHttpSupport.class);
61	    public static final String DEFAULT_CONTENT_TYPE_ON_EXCEPTION = "text/plain; charset=utf-8";
62	
63	    private VertxPlatformHttpSupport() {
64	    }
65	
66	    static Object toHttpResponse(
67	            RoutingContext ctx, Message message, HeaderFilterStrategy headerFilterStrategy,
68	            boolean muteExceptions) {
69	        final Exchange exchange = message.getExchange();
70	
71	        HttpServerResponse response = ctx.response();
72	        final int code = determineResponseCode(exchange, message.getBody());
73	        response.setStatusCode(code);
74	
75	        // copy headers from Message to Response
76	        if (headerFilterStrategy != null) {
77	            copyMessageHeadersToResponse(response, ctx.pathParams(), message, headerFilterStrategy, exchange);
78	        }
79	
80	        final Object body = getBody(message, muteExceptions, exchange);
81	
82	        // set the content-length if it can be determined, or chunked encoding
83	        final Integer length = determineContentLength(body);
84	        if (length != null) {
85	            response.putHeader("Content-Length", String.valueOf(length));
86	        } else {
87	            response.setChunked(true);
88	        }
89	
90	        // set the content type in the response.
91	        final String contentType = MessageHelper.getContentType(message);
92	        if (contentType != null) {
93	            // set content-type
94	            response.putHeader("Content-Type", contentType);
95	        }
96	        return body;
97	    }
98	
99	    private static Object getBody(Message message, boolean muteExceptions, Exchange exchange) {
100	        final Exception exception = exchange.getException();
101	
102	        if (exception != null) {
103	            return handleExceptions(message, muteExceptions, exception, exchange);
104	        }
105	        return message.getBody();
106	    }
107	
108	    private static Object handleExceptions(Message message, boolean muteExceptions, Exception exception, Exchange exchange) {
109	        Object body;
110	        if (muteExceptions) {
111	            body = ""; // do not include stacktrace in body
112	            // force content type to be text/plain as that is what the stacktrace is
113	            message.setHeader(Exchange.CONTENT_TYPE, DEFAULT_CONTENT_TYPE_ON_EXCEPTION);
114	        } else {
115	            // we failed due an exception so print it as plain text
116	            final String stackTrace = ExceptionHelper.stackTraceToString(exception);
117	
118	            // the body should then be the stacktrace
119	            body = ByteBuffer.wrap(stackTrace.getBytes(StandardCharsets.UTF_8));
120	            // force content type to be text/plain as that is what the stacktrace is
121	            message.setHeader(Exchange.CONTENT_TYPE, DEFAULT_CONTENT_TYPE_ON_EXCEPTION);
122	        }
123	
124	        return body;
125	    }
126	
127	    private static void copyMessageHeadersToResponse(
128	            HttpServerResponse response, Map<String, String> pathParams,
129	            Message message, HeaderFilterStrategy headerFilterStrategy, Exchange exchange) {
130	        final TypeConverter tc = exchange.getContext().getTypeConverter();
131	
132	        for (Map.Entry<String, Object> entry : message.getHeaders().entrySet()) {
133	            final String key = entry.getKey();
134	
135	            // skip headers that are path-params as we do not want to leak them back to the caller
136	            if (pathParams.containsKey(key)) {
137	                continue;
138	            }
139	
140	            final Object value = entry.getValue();
141	            // use an iterator as there can be multiple values. (must not use a delimiter)
142	            final Iterator<?> it = ObjectHelper.createIterator(value, null, true);
143	
144	            putHeader(response, headerFilterStrategy, exchange, it, tc, key);
145	        }
146	    }
147	
148	    private static void putHeader(
149	            HttpServerResponse response, HeaderFilterStrategy headerFilterStrategy, Exchange exchange, Iterator<?> it,
150	            TypeConverter tc, String key) {
151	
152	        HttpUtil.applyHeader(headerFilterStrategy, exchange, it, tc, key,
153	                (values, firstValue) -> applyHeader(response, key, values, firstValue));
154	    }
155	
156	    private static void applyHeader(HttpServerResponse response, String key, List<String> values, String firstValue) {
157	        if (values != null) {
158	            response.putHeader(key, values);
159	        } else if (firstValue != null) {
160	            response.putHeader(key, firstValue);
161	        }
162	    }
163	
164	    static Integer determineContentLength(Object body) {
165	        if (body instanceof byte[] byteArray) {
166	            return byteArray.length;
167	        } else if (body instanceof ByteBuffer bytebuffer) {
168	            return bytebuffer.remaining();
169	        }
170	        return null;
171	    }
172	
173	    static Future<Void> writeResponse(
174	            RoutingContext ctx, Exchange camelExchange, HeaderFilterStrategy headerFilterStrategy, boolean muteExceptions) {
175	        final Promise<Void> promise = Promise.promise();
176	
177	        // Nothing to do if the response is already ended due to request timeout etc
178	        if (ctx.response().ended()) {
179	            promise.complete();
180	            return promise.future();
181	        }
182	
183	        try {
184	            final Object body = toHttpResponse(ctx, camelExchange.getMessage(), headerFilterStrategy, muteExceptions);
185	            if (body == null) {
186	                LOGGER.trace("No payload to send as reply for exchange: {}", camelExchange);
187	                ctx.end();
188	                promise.complete();
189	            } else if (body instanceof String string) {
190	                ctx.end(string);
191	                promise.complete();
192	            } else if (body instanceof InputStream inputstream) {
193	                writeResponseAs(promise, ctx, inputstream);
194	            } else if (body instanceof Buffer buffer) {
195	                ctx.end(buffer);
196	                promise.complete();
197	            } else if (body instanceof ByteBuffer bb) {
198	                writeResponseAs(promise, ctx, bb);
199	            } else {
200	                writeResponseAsFallback(promise, camelExchange, body, ctx);
201	            }
202	        } catch (Exception e) {
203	            promise.fail(e);
204	        }
205	
206	        return promise.future();
207	    }
208	
209	    private static void writeResponseAsFallback(Promise<Void> promise, Exchange camelExchange, Object body, RoutingContext ctx)
210	            throws NoTypeConversionAvailableException {
211	        final TypeConverter tc = camelExchange.getContext().getTypeConverter();
212	
213	        // favour input stream first
214	        InputStream is = tc.tryConvertTo(InputStream.class, camelExchange, body);
215	        if (is != null) {
216	            writeResponseAs(promise, ctx, is);
217	            return;
218	        }
219	        // then fallback to byte buffer
220	        ByteBuffer bb = tc.tryConvertTo(ByteBuffer.class, camelExchange, body);
221	        if (bb != null) {
222	            writeResponseAs(promise, ctx, bb);
223	            return;
224	        }
225	        throw new NoTypeConversionAvailableException(body, InputStream.class);
226	    }
227	
228	    private static void writeResponseAs(Promise<Void> promise, RoutingContext ctx, ByteBuffer bb) {
229	        final Buffer b = Buffer.buffer(bb.capacity());
230	        b.setBytes(0, bb);
231	        ctx.end(b);
232	        promise.complete();
233	    }
234	
235	    private static void writeResponseAs(Promise<Void> promise, RoutingContext ctx, InputStream is) {
236	        HttpServerResponse response = ctx.response();
237	        Vertx vertx = ctx.vertx();
238	        Context context = vertx.getOrCreateContext();
239	
240	        // Process the InputStream async to avoid blocking the Vert.x event loop on large responses
241	        AsyncInputStream asyncInputStream = new AsyncInputStream(vertx, context, is);
242	        asyncInputStream.exceptionHandler(promise::fail);
243	        asyncInputStream.endHandler(event -> endHandler(promise, response, asyncInputStream));
244	
245	        // Pump the InputStream content into the HTTP response WriteStream
246	        Pump pump = Pump.pump(asyncInputStream, response);
247	        context.runOnContext(event -> pump.start());
248	    }
249	
250	    private static void endHandler(Promise<Void> promise, HttpServerResponse response, AsyncInputStream asyncInputStream) {
251	        response.end().onComplete(result -> onComplete(promise, asyncInputStream));
252	    }
253	
254	    private static void onComplete(Promise<Void> promise, AsyncInputStream asyncInputStream) {
255	        asyncInputStream.close(closeResult -> promise.complete());
256	    }
257	
258	    static void populateCamelHeaders(
259	            RoutingContext ctx,
260	            Map<String, Object> headersMap,
261	            Exchange exchange,
262	            HeaderFilterStrategy headerFilterStrategy) {
263	
264	        final HttpServerRequest request = ctx.request();
265	        headersMap.put(Exchange.HTTP_PATH, ctx.normalizedPath());
266	
267	        if (headerFilterStrategy != null) {
268	            applyHeaderFilterStrategy(ctx, headersMap, exchange, headerFilterStrategy, request);
269	        }
270	
271	        // Path parameters
272	        for (Map.Entry<String, String> en : ctx.pathParams().entrySet()) {
273	            appendEntry(headersMap, en.getKey(), en.getValue());
274	        }
275	
276	        SocketAddress localAddress = request.localAddress();
277	        if (localAddress != null) {
278	            headersMap.put(VertxPlatformHttpConstants.LOCAL_ADDRESS, localAddress);
279	        }
280	
281	        SocketAddress remoteAddress = request.remoteAddress();
282	        if (remoteAddress != null) {
283	            headersMap.put(VertxPlatformHttpConstants.REMOTE_ADDRESS, remoteAddress);
284	        }
285	
286	        // NOTE: these headers is applied using the same logic as camel-http/camel-jetty to be consistent
287	        headersMap.put(Exchange.HTTP_METHOD, request.method().toString());
288	        // strip query parameters from the uri
289	        headersMap.put(Exchange.HTTP_URL, request.absoluteURI());
290	        // uri is without the host and port
291	        headersMap.put(Exchange.HTTP_URI, request.uri());
292	        headersMap.put(Exchange.HTTP_QUERY, request.query());
293	        headersMap.put(Exchange.HTTP_RAW_QUERY, request.query());
294	    }
295	
296	    // Note: this is in the hot path of the platform http, so be mindful with performance here
297	    private static void applyHeaderFilterStrategy(
298	            RoutingContext ctx, Map<String, Object> headersMap, Exchange exchange, HeaderFilterStrategy headerFilterStrategy,
299	            HttpServerRequest request) {
300	        final MultiMap requestHeaders = request.headers();
301	        applyAuthHeaders(headersMap, exchange, headerFilterStrategy, requestHeaders);
302	        applyHeaders(headersMap, exchange, headerFilterStrategy, requestHeaders);
303	
304	        // process uri parameters as headers
305	        final MultiMap pathParameters = ctx.queryParams();
306	        // continue if the map is not empty, otherwise there are no params
307	        if (!pathParameters.isEmpty()) {
308	            applyHeaders(headersMap, exchange, headerFilterStrategy, pathParameters);
309	        }
310	    }
311	
312	    private static void applyHeaders(
313	            Map<String, Object> headersMap, Exchange exchange, HeaderFilterStrategy headerFilterStrategy,
314	            MultiMap requestHeaders) {
315	
316	        final List<Map.Entry<String, String>> entries = requestHeaders.entries();
317	        for (var entry : entries) {
318	            final String name = entry.getKey();
319	            final String value = entry.getValue();
320	
321	            // add the headers one by one, and use the header filter strategy
322	            if (!headerFilterStrategy.applyFilterToExternalHeaders(name, value, exchange)) {
323	                appendEntry(headersMap, name, value);
324	            }
325	        }
326	    }
327	
328	    private static void applyAuthHeaders(
329	            Map<String, Object> headersMap, Exchange exchange, HeaderFilterStrategy headerFilterStrategy,
330	            MultiMap requestHeaders) {
331	        final String authorization = requestHeaders.get("authorization");
332	        // store a special header that this request was authenticated using HTTP Basic
333	        if (authorization != null && authorization.trim().startsWith("Basic")) {
334	            if (!headerFilterStrategy.applyFilterToExternalHeaders(Exchange.AUTHENTICATION, "Basic", exchange)) {
335	                appendEntry(headersMap, Exchange.AUTHENTICATION, "Basic");
336	            }
337	        }
338	    }
339	
340	    static boolean isMultiPartFormData(RoutingContext ctx) {
341	        return isContentTypeMatching(ctx, HttpHeaderValues.MULTIPART_FORM_DATA.toString());
342	    }
343	
344	    static boolean isFormUrlEncoded(RoutingContext ctx) {
345	        return isContentTypeMatching(ctx, HttpHeaderValues.APPLICATION_X_WWW_FORM_URLENCODED.toString());
346	    }
347	
348	    private static boolean isContentTypeMatching(RoutingContext ctx, String expectedContentType) {
349	        String contentType = ctx.parsedHeaders().contentType().value();
350	        boolean match = false;
351	        if (org.apache.camel.util.ObjectHelper.isNotEmpty(contentType)) {
352	            String lowerCaseContentType = contentType.toLowerCase();
353	            match = lowerCaseContentType.startsWith(expectedContentType);
354	        }
355	        return match;
356	    }
