private void doRead(Buffer writeBuff, int offset, ByteBuffer buffer, long position, Handler<AsyncResult<Buffer>> handler) {
    vertx.executeBlocking(() -> channel.read(buffer))
            .onComplete(result -> {
                if (result.succeeded()) {
                    // Emit whatever was read immediately (EOF yields an empty buffer as sentinel).
                    // Never loop to fill the ByteBuffer: that blocks SSE and other streaming
                    // responses that produce small chunks, and compact() would carry stale bytes
                    // into the next emission when an EOF follows a partial read.
                    context.runOnContext((v) -> {
                        buffer.flip();
                        writeBuff.setBytes(offset, buffer);
                        buffer.clear();
                        handler.handle(Future.succeededFuture(writeBuff));
                    });
                } else {
                    context.runOnContext((v) -> handler.handle(Future.failedFuture(result.cause())));
                }
            });
}

